mapper.select:
select orders.*, business.name as business_name, users.name as user_name, users.phone as user_phone
from orders
left join business on orders.business_id = business.id
left join users on orders.user_id = users.id

    and orders.id = #{id}
    and orders.user_id = #{userId}
    and orders.business_id = #{businessId}
    and orders.goods_id = #{goodsId}
    and cast(orders.order_id as text) like concat('%', #{orderId}, '%')
    and orders.status = #{status}

order by orders.id desc
